// Función para convertir hora string (HH:MM:SS) a minutos desde medianoche
function timeToMinutes(timeStr) {
  const [hours, minutes, seconds] = timeStr.split(':').map(Number);
  return hours * 60 + minutes;
}

// Función para convertir minutos a formato HH:MM:SS
function minutesToTime(minutes) {
  const hours = Math.floor(minutes / 60);
  const mins = minutes % 60;
  return `${hours.toString().padStart(2, '0')}:${mins.toString().padStart(2, '0')}:00`;
}

// Función para convertir fecha ISO a minutos del día
function isoToMinutes(isoString) {
  const date = new Date(isoString);
  return date.getHours() * 60 + date.getMinutes();
}

// Función para obtener la fecha de un string ISO
function getDateFromISO(isoString) {
  const date = new Date(isoString);
  return date.toISOString().split('T')[0];
}

// Función para obtener las fechas de la semana (lunes a viernes)
function getWeekDates(startDate) {
  const dates = [];
  const start = new Date(startDate);

  // Encontrar el lunes de esta semana
  const dayOfWeek = start.getDay();
  const mondayOffset = dayOfWeek === 0 ? -6 : 1 - dayOfWeek; // Si es domingo (0), retroceder 6 días
  const monday = new Date(start);
  monday.setDate(start.getDate() + mondayOffset);

  // Generar lunes a viernes
  for (let i = 0; i < 5; i++) {
    const date = new Date(monday);
    date.setDate(monday.getDate() + i);
    dates.push(date.toISOString().split('T')[0]);
  }

  return dates;
}

// Función para generar slots disponibles en un día específico
function generateDaySlots(taller, eventos, targetDate) {
  const apertura = timeToMinutes(taller.Apertura);
  const cierre = timeToMinutes(taller.Cierre);
  const inicioAlmuerzo = timeToMinutes(taller["Inicio Almuerzo"]);
  const finAlmuerzo = timeToMinutes(taller["Fin Almuerzo"]);
  const SLOT_DURATION = 60;

  // Filtrar eventos para este taller y fecha específica
  const eventosDelDia = eventos.filter(evento => {
    if (!evento.json || !evento.json.organizer || !evento.json.start) return false;
    const eventoDate = getDateFromISO(evento.json.start.dateTime);
    return evento.json.organizer.email === taller.Id_Calendario && eventoDate === targetDate;
  });

  // Crear todos los slots posibles del día
  const slotsDisponibles = [];

  // Slots de mañana (apertura hasta inicio almuerzo)
  for (let time = apertura; time + SLOT_DURATION <= inicioAlmuerzo; time += SLOT_DURATION) {
    slotsDisponibles.push({
      inicio: time,
      fin: time + SLOT_DURATION,
      ocupado: false
    });
  }

  // Slots de tarde (fin almuerzo hasta cierre, sin incluir el último slot)
  for (let time = finAlmuerzo; time + SLOT_DURATION < cierre; time += SLOT_DURATION) {
    slotsDisponibles.push({
      inicio: time,
      fin: time + SLOT_DURATION,
      ocupado: false
    });
  }

  // Marcar slots ocupados por eventos
  eventosDelDia.forEach(evento => {
    const eventoInicio = isoToMinutes(evento.json.start.dateTime);
    const eventoFin = isoToMinutes(evento.json.end.dateTime);

    slotsDisponibles.forEach(slot => {
      // Si hay solapamiento entre el slot y el evento
      if (slot.inicio < eventoFin && slot.fin > eventoInicio) {
        slot.ocupado = true;
      }
    });
  });

  // Retornar solo slots libres
  return slotsDisponibles.filter(slot => !slot.ocupado);
}

// Función principal para generar 1 turno random por día de la semana
function generateWeeklyAvailability(talleres, eventos, startDate) {
  const weekDates = getWeekDates(startDate);
  const availability = [];

  talleres.forEach(taller => {
    weekDates.forEach(date => {
      const slotsLibres = generateDaySlots(taller, eventos, date);

      if (slotsLibres.length > 0) {
        // Seleccionar un slot aleatorio
        const randomIndex = Math.floor(Math.random() * slotsLibres.length);
        const slotElegido = slotsLibres[randomIndex];

        availability.push({
          taller: taller.Talleres,
          fecha: date,
          horaInicio: minutesToTime(slotElegido.inicio),
          horaFin: minutesToTime(slotElegido.fin),
          tecnico: taller.Técnicos,
          asesorServicio: taller["Asesor de Servicio"],
          idCalendario: taller.Id_Calendario,
          duracion: 60
        });
      }
    });
  });

  return availability;
}

// Código para n8n
const talleresRaw = $('Get row(s) in sheet').all() || [];
const talleres = talleresRaw.map(item => item.json);
console.log('talleres procesados:', talleres.length);

const eventosRaw = $input.all() || [];
const eventos = eventosRaw.filter(item => item.json && Object.keys(item.json).length > 0);
console.log('eventos procesados:', eventos.length);

// Usar fecha actual como punto de partida para la semana
const startDate = new Date().toISOString().split('T')[0];
console.log('fecha inicio:', startDate);

// Generar disponibilidades para la semana
const disponibilidades = generateWeeklyAvailability(talleres, eventos, startDate);
console.log('disponibilidades generadas:', disponibilidades.length);

// Preparar salida para n8n
const output = [];

if (disponibilidades.length === 0) {
  output.push({
    json: {
      mensaje: "No hay disponibilidades para esta semana",
      semana: startDate,
      disponibilidades: []
    }
  });
} else {
  // Agrupar por día de la semana
  const porDia = disponibilidades.reduce((acc, disp) => {
    const fecha = disp.fecha;
    if (!acc[fecha]) {
      acc[fecha] = [];
    }
    acc[fecha].push(disp);
    return acc;
  }, {});

  // Crear salida estructurada
  output.push({
    json: {
      semanaInicio: startDate,
      totalTurnos: disponibilidades.length,
      turnosPorDia: porDia,
      todosLosTurnos: disponibilidades
    }
  });
}

return output;

